<template><section v-if="account.tab==='classroom'||account.lesson" class="campus-modal mc-panel classroom"><header><h2>高教授 · 方块城市导论</h2><button class="mc-btn" @click="leave">{{account.lesson?'离座中断':'关闭'}}</button></header><p>自产图文占位课程 · 10分钟 · 完整观看 +10积分</p><template v-if="!account.lesson"><label>播放速度 <select v-model.number="speed"><option :value="1">1×</option><option :value="1.25">1.25×</option></select></label><p>选择固定座位（共50席）</p><div class="seats"><button v-for="n in 50" :key="n" class="mc-btn small" :class="{active:seat===n}" @click="seat=n">{{n}}</button></div><button class="mc-btn primary" :disabled="busy" @click="start">落座并开始</button></template><template v-else><div class="lecture"><span>讲义 {{page+1}} / {{slides.length}}</span><h3>{{slides[page].title}}</h3><p>{{slides[page].body}}</p><small>高教授在讲台授课 · 座位 {{seat}} · {{speed}}×</small></div><progress :value="watched" :max="600"></progress><p>服务端已确认 {{Math.floor(watched)}} / 600 秒</p><p v-if="needsConfirm" class="error">计分已暂停，请确认仍在观看。</p><button v-if="needsConfirm" class="mc-btn primary" :disabled="busy" @click="send('confirm')">我在观看</button><button class="mc-btn primary" :disabled="busy||watched<600" @click="send('finish')">完成并结算</button><p class="muted">每5分钟确认一次；离座即中断。切后台不计时，超过2分钟本堂课无积分。</p></template><p role="alert" class="error">{{error}}</p></section></template>
<script setup>
import {ref,computed,onMounted,onBeforeUnmount} from 'vue'
import {account,api,eventKey,refreshEconomy} from '../campus/session.js'
import {store,toast} from '../game/store.js'
import {G} from '../game/instance.js'
const seat=ref(1),speed=ref(1),busy=ref(false),error=ref(''),watched=ref(0),needsConfirm=ref(false)
const slides=[{title:'从方块观察城市',body:'城市由街道、建筑和公共空间构成。观察广东工业大学的校园入口，找到行人动线与建筑之间的联系。'},{title:'光与空间',body:'同一座建筑，在清晨与黄昏会呈现不同的层次。摄影时尝试改变角度，让明暗帮助表达主体。'},{title:'共享校园',body:'教室、图书馆、宿舍和交通站点共同构成日常校园生活。想一想，你最喜欢哪一处公共空间？'},{title:'记录与表达',body:'拍照记录自己的发现，用一句话描述你在画面里看到的故事。尊重他人隐私，发布前认真检查内容。'},{title:'下课之后',body:'课程即将结束。走到图书馆拍一张照片，或去广州看看城市地标，把今天的观察分享出来。'}]
const page=computed(()=>Math.min(slides.length-1,Math.floor(watched.value/120)))
let timer
function unseat(){if(G.game){G.game.player.scripted=null;G.game.player.frozen=false;G.game.player.char.setAnim('idle')}account.lesson=null;account.tab=null;store.ui.panel=null}
async function start(){if(account.guest)return error.value='游客不可参与课程结算';const game=G.game,room=game?.landmarks.byId['school:gdut-classroom'];if(!room||Math.hypot(game.player.pos.x-room.x,game.player.pos.z-room.z)>30)return error.value='请先进入广东工业大学教室';busy.value=true;try{account.lesson=await api('/lessons/start',{key:eventKey(),seat:seat.value,speed:speed.value});watched.value=0;needsConfirm.value=false;const row=Math.floor((seat.value-1)/10),col=(seat.value-1)%10;const p=game.landmarks.toWorld('school:gdut-classroom',-9+col*2,0.5,1+row*2.5);game.player.teleport(p.x,p.y,p.z,0);game.player.scripted=()=>{game.player.char.setAnim('sit')};store.ui.panel='classroom';game.input.exitLock()}catch(e){error.value=e.message}finally{busy.value=false}}
async function send(type){if(!account.lesson||busy.value)return;busy.value=true;try{error.value='';const result=await api('/lessons/'+account.lesson.id+'/event',{key:eventKey(),type});if(result.watched!=null)watched.value=result.watched;needsConfirm.value=!!result.needsConfirm;if(result.awarded){toast('下课啦！+10积分，升级奖励已进入服务端账本','reward');await refreshEconomy();unseat()}else if(result.status==='interrupted'){toast('课程已中断，本堂课无积分','warn');unseat()}}catch(e){error.value=e.message}finally{busy.value=false}}
async function leave(){if(account.lesson)await send('leave');unseat()}
function visibility(){if(account.lesson)send(document.hidden?'hidden':'visible')}
onMounted(()=>{timer=setInterval(()=>{if(!document.hidden)send('pulse')},15000);document.addEventListener('visibilitychange',visibility)})
onBeforeUnmount(()=>{clearInterval(timer);document.removeEventListener('visibilitychange',visibility)})
</script>
<style scoped>.seats{display:grid;grid-template-columns:repeat(10,1fr);gap:5px;margin:18px 0}.seats button{padding:8px 2px}.lecture{padding:28px;background:#294238;border:6px solid #8d7153;margin:20px 0;min-height:220px}.lecture h3{font-size:26px;color:#ffe6a2}.lecture p{line-height:2}.classroom progress{width:100%;accent-color:#a4d777}.classroom{z-index:48}@media(max-width:600px){.seats{grid-template-columns:repeat(5,1fr)}.lecture{padding:16px}}</style>
